-- =============================================================================
-- 505 — LE CAHIER D'EXERCICES DE 2DE (partie 7)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 505 --niveau 2de --fichiers francais.n2,grec.n1,histoire-geo.n1 --suffixe 7 > supabase/contenu/505_exercices_2de_7.sql
--
-- 75 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n2             36 exercices · 12 chapitres
--   grec.n1                  9 exercices · 3 chapitres
--   histoire-geo.n1         30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('67baaeb0-9df3-58be-85b7-89fe88eae630'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Cinq romans sur trois siècles","competence":"se-reperer-temps","situation":"Au CDI, la professeure documentaliste a tendu une frise sur le mur : cinq romans, du siècle des Lumières à la Seconde Guerre mondiale. À toi de la lire comme un historien de la littérature.","documents":[{"id":"frise","type":"frise","titre":"Le roman, de 1700 à 1950","debut":1700,"fin":1950,"pas":50,"periodes":[{"id":"z1","debut":1700,"fin":1800,"nom":"XVIIIe siècle","teinte":"ambre"},{"id":"z2","debut":1800,"fin":1900,"nom":"XIXe siècle","teinte":"turquoise"},{"id":"z3","debut":1900,"fin":1950,"nom":"XXe siècle","teinte":"rose"}],"evenements":[{"id":"z4","date":1759,"nom":"Candide"},{"id":"z5","date":1782,"nom":"Les Liaisons dangereuses"},{"id":"z6","date":1835,"nom":"Le Père Goriot"},{"id":"z7","date":1885,"nom":"Germinal"},{"id":"z8","date":1942,"nom":"L’Étranger"}],"source":"Dates de première publication"}],"questions":[{"enonce":"Touche le roman de la frise qui est écrit **entièrement par lettres**.","aide":"C’est un roman de Laclos.","type":"zone","document":"frise","multiple":false},{"enonce":"Touche les **deux romans** de la frise publiés au **XIXe siècle**.","aide":"Repère la période colorée du XIXe siècle : quels titres y tombent ?","type":"zone","document":"frise","multiple":true},{"enonce":"Relie chaque siècle à ce que devient le roman.","aide":"Pense aux mots clés du cours : déguiser, milieu, douter, réel.","type":"association","gauche":[{"id":"g0","texte":"XVIIIe siècle"},{"id":"g1","texte":"XIXe siècle"},{"id":"g2","texte":"XXe siècle"},{"id":"g3","texte":"XXIe siècle"}],"droite":[{"id":"d0","texte":"Le récit doute de lui-même"},{"id":"d1","texte":"Retour du récit du réel"},{"id":"d2","texte":"Il se déguise pour conquérir sa légitimité"},{"id":"d3","texte":"Le personnage est déterminé par son milieu"}]},{"enonce":"Combien d’années séparent la parution de **Candide** de celle de **L’Étranger** ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"Ce sont **Les Liaisons dangereuses** : un roman par lettres, genre à la mode au XVIIIe siècle."},{"cle":{"type":"zone","ids":["z6","z7"]},"explication":"**Le Père Goriot** (1835) et **Germinal** (1885) sont publiés entre 1800 et 1900."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"Au XVIIIe, le roman se **déguise** (lettres, mémoires, conte) ; au XIXe, le **milieu** détermine le personnage ; au XXe, le récit **doute de lui-même** ; au XXIe, il revient au **réel**."},{"cle":{"type":"nombre","valeur":183,"tolerance":0},"affichage":"183 ans","explication":"1942 − 1759 = **183 ans**."}]$ex$::jsonb),
  ('67baaeb0-9df3-58be-85b7-89fe88eae630'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois regards sur Lina","competence":"analyser-texte","situation":"Pour son atelier d’écriture, Samia a raconté trois fois la même scène en changeant seulement le point de vue. Elle te demande d’identifier ses choix.","documents":[{"id":"scenes","type":"texte","genre":"recit","titre":"Une scène, trois versions","blocs":["Lina referma la porte sans bruit. Elle savait que Paul avait menti depuis la veille, et cette certitude lui serrait la gorge.","Lina referma la porte sans bruit. Paul, assis à la table, ne leva pas la tête. Elle resta une minute debout, les mains dans les poches.","Lina referma la porte sans bruit. Elle ignorait que Paul préparait déjà son départ et que, dans trois jours, la maison serait vide."],"source":"Texte écrit pour l’exercice"},{"id":"rythme","type":"tableau","titre":"Quatre phrases, quatre vitesses","colonnes":["Phrase"],"lignes":[["Pendant trois ans, il travailla à l’usine."],["— Tu viens ? demanda-t-elle. — Non, répondit-il."],["Trois ans plus tard, il rentra."],["La maison était longue, grise, aux volets verts."]],"enteteLignes":false,"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Dans la **première version**, touche le verbe qui nous donne accès à la **pensée** de Lina.","aide":"Quel verbe dit ce que Lina sait en elle-même ?","type":"zone","document":"scenes","multiple":false},{"enonce":"Relie chaque version au point de vue adopté.","aide":"Qui connaît les pensées ? Qui ne voit que les gestes ? Qui sait plus que le personnage ?","type":"association","gauche":[{"id":"g0","texte":"Version 1"},{"id":"g1","texte":"Version 2"},{"id":"g2","texte":"Version 3"}],"droite":[{"id":"d0","texte":"Point de vue zéro (le narrateur sait tout)"},{"id":"d1","texte":"Focalisation externe"},{"id":"d2","texte":"Focalisation interne"}]},{"enonce":"Range chaque phrase selon le rythme du récit qu’elle produit.","aide":"Résumer, raconter au rythme réel, sauter, décrire : quelle phrase fait quoi ?","type":"categories","categories":[{"id":"c0","texte":"Sommaire"},{"id":"c1","texte":"Scène"},{"id":"c2","texte":"Ellipse"},{"id":"c3","texte":"Pause"}],"items":[{"id":"i0","texte":"— Tu viens ? demanda-t-elle. — Non, répondit-il."},{"id":"i1","texte":"Pendant trois ans, il travailla à l’usine."},{"id":"i2","texte":"Trois ans plus tard, il rentra."},{"id":"i3","texte":"La maison était longue, grise, aux volets verts."}]},{"enonce":"Le narrateur de la première version est-il l’auteur du texte, c’est-à-dire Samia ?","aide":"Souviens-toi de la règle de base : le narrateur n’est pas…","type":"choix","options":[{"id":"a","texte":"Oui, dès qu’il raconte à la troisième personne"},{"id":"b","texte":"Non, c’est toujours un des personnages cités"},{"id":"c","texte":"Non : c’est une voix construite par le texte"},{"id":"d","texte":"Oui : le narrateur est toujours l’auteur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"Le verbe **savait** ouvre la conscience de Lina : on ne connaît que ce qu’elle sait, c’est la focalisation interne."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"V.1 : on ne sait que ce que Lina sait (**interne**). V.2 : on ne voit que des gestes (**externe**). V.3 : le narrateur sait ce que Lina ignore (**point de vue zéro**)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c3"}},"explication":"Le **sommaire** résume trois ans, la **scène** donne le dialogue en direct, l’**ellipse** saute un moment, la **pause** décrit pendant que l’histoire s’arrête."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le narrateur est une **voix construite par le texte** : ce n’est pas l’auteur, même quand le récit paraît très proche de lui."}]$ex$::jsonb),
  ('67baaeb0-9df3-58be-85b7-89fe88eae630'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le logement du troisième","competence":"analyser-texte","situation":"Dans un blog littéraire, une lycéenne a imité le style du roman réaliste. Lis son extrait avec le tableau des trois siècles pour dire ce que fait un roman du XIXe siècle.","documents":[{"id":"tab","type":"tableau","titre":"Trois siècles en un tableau","colonnes":["Le siècle","Ce que le roman y devient","Ses auteurs"],"lignes":[["XVIIIe","Il conquiert sa légitimité en se déguisant","Laclos, Prévost, Voltaire"],["XIXe","Réalisme et naturalisme : le personnage est déterminé par son milieu","Balzac, Flaubert, Zola"],["XXe","Le récit doute de lui-même","Proust, Céline, Camus, Nouveau Roman"]],"enteteLignes":false},{"id":"logis","type":"texte","genre":"recit","titre":"Un logement, un revenu","blocs":["Madame Rolland occupait au troisième un logement de deux pièces. Sur la table, une toile cirée recousue ; à la fenêtre, des rideaux trop courts ; dans le poêle, de la braise qu’on ménageait.","Elle ne savait pas encore que l’huissier viendrait lundi. Dans cette rue, comme dans tant d’autres, on tombait vite et l’on ne remontait guère."],"source":"Extrait écrit pour l’exercice, à la manière du roman réaliste"}],"questions":[{"enonce":"Touche les **deux mots** qui disent, par une réparation ou une économie, que l’argent manque.","aide":"Cherche un objet réparé et un geste d’économie, dans le premier paragraphe.","type":"zone","document":"logis","multiple":true},{"enonce":"Dans le tableau, touche la case qui annonce **la thèse** que ce texte illustre : la place sociale décide du sort du personnage.","aide":"Cherche la ligne du siècle de Balzac, Flaubert et Zola.","type":"zone","document":"tab","multiple":false},{"enonce":"Dans le second paragraphe, « Elle ne savait pas encore que l’huissier viendrait lundi » : de quel point de vue s’agit-il ?","aide":"Madame Rolland ignore quelque chose. Qui le sait alors ?","type":"choix","options":[{"id":"a","texte":"La focalisation externe : on ne voit que ses gestes"},{"id":"b","texte":"Un monologue intérieur de Madame Rolland"},{"id":"c","texte":"Le point de vue zéro : le narrateur sait ce qu’elle ignore"},{"id":"d","texte":"La focalisation interne : on ne sait que ce qu’elle sait"}],"multiple":false},{"enonce":"Complète la phrase du cours.","aide":"Monter, tomber, tenir : de quoi parle-t-on ?","type":"trous","segments":["Le roman du XIXe siècle raconte moins des aventures que des ",0," : monter, tomber, tenir."],"banque":["batailles","places sociales","duels","voyages"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m32"]},"explication":"Une toile cirée **recousue** et de la braise qu’on **ménageait** : ces détails matériels disent la gêne sans la nommer."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La case du **XIXe siècle** : le personnage y est déterminé par son milieu, ce que montrent le logement et l’huissier."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le narrateur connaît l’avenir que le personnage **ignore** : c’est le **point de vue zéro**."},{"cle":{"type":"trous","trous":[["places sociales"]]},"affichage":"places sociales","explication":"Il raconte des **places sociales** : monter, tomber, tenir dans la société."}]$ex$::jsonb),
  ('30417519-e1db-5a1c-a8ec-25d7f3771ef0'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Soirée Maupassant au CDI","competence":"analyser-document","situation":"Le club de lecture du lycée annonce quatre nouvelles de Maupassant, projetées à la suite. Sur l’affiche, chaque titre n’a qu’un indice. Retrouve ce que chaque nouvelle met en accusation.","documents":[{"id":"aff","type":"fiche","modele":"affiche","entete":"Soirée Maupassant","sousTitre":"Quatre nouvelles, une même plume","emoji":"📚","teinte":"violet","lignes":[{"texte":"Boule de suif","valeur":"Une diligence, la guerre de 1870","id":"z1"},{"texte":"La Parure","valeur":"Un bal, un bijou prêté","id":"z2"},{"texte":"Aux champs","valeur":"Deux familles de paysans","id":"z3"},{"texte":"Mon oncle Jules","valeur":"Un oncle qu’on croit riche","id":"z4"}],"pied":"Jeudi, au CDI — entrée libre"}],"questions":[{"enonce":"Touche la nouvelle qui met en accusation **la vanité** et le culte de l’apparence.","aide":"Un bijou prêté pour briller, cela rappelle quelle nouvelle ?","type":"zone","document":"aff","multiple":false},{"enonce":"Touche les **deux nouvelles** où le cours voit l’hypocrisie familiale et l’argent.","aide":"Cherche les histoires de familles.","type":"zone","document":"aff","multiple":true},{"enonce":"Complète la fiche de l’auteur.","aide":"Son maître était aussi un grand romancier du XIXe siècle.","type":"trous","segments":["Élève de ",0,", Maupassant a écrit environ ",1," nouvelles, souvent terminées par une ",2," qui retourne le sens."],"banque":["trois cents","cent","Zola","morale","chute","Flaubert"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**La Parure** : dix ans de misère pour rembourser un bijou qui était faux."},{"cle":{"type":"zone","ids":["z3","z4"]},"explication":"**Aux champs** et **Mon oncle Jules** mettent en scène l’hypocrisie familiale et l’argent."},{"cle":{"type":"trous","trous":[["flaubert"],["trois cents","300"],["chute"]]},"affichage":"Flaubert · trois cents · chute","explication":"Élève de **Flaubert**, il a écrit environ **trois cents** nouvelles, souvent avec une **chute**."}]$ex$::jsonb),
  ('30417519-e1db-5a1c-a8ec-25d7f3771ef0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le manteau de Madame Lefort","competence":"analyser-texte","situation":"Pour le club de lecture, Rayan a écrit une nouvelle à la manière de Maupassant : un détail vrai, une ironie froide, une chute. Lis-la et repère chaque procédé.","documents":[{"id":"manteau","type":"texte","genre":"recit","titre":"Le manteau","blocs":["Madame Lefort avait épousé un petit employé de la préfecture et ne le lui pardonnait pas. Chaque dimanche, elle passait son grand manteau de fourrure, ses gants reprisés et ses bottines éculées, puis traversait la place d’un pas de duchesse.","Monsieur Lefort suivait, un pas derrière, flatté qu’on le crût marié à une dame. Quelle chance, après tout, d’avoir une femme si élégante !","Le jour de leur anniversaire, un voisin admira le manteau. « Du renard argenté, n’est-ce pas ? » Madame Lefort sourit sans répondre. Le soir, en le rangeant, elle déchira la doublure ; son mari la vit pâlir. Sous l’étiquette, on lisait : « lapin teint »."],"source":"Nouvelle écrite pour l’exercice, à la manière de Maupassant"}],"questions":[{"enonce":"Touche les **deux mots** qui trahissent la gêne derrière l’élégance affichée.","aide":"Deux adjectifs disent l’usure des accessoires.","type":"zone","document":"manteau","multiple":true},{"enonce":"Classe chaque phrase selon la façon dont les paroles ou pensées sont rapportées.","aide":"Guillemets ? Verbe introducteur et « que » ? Ni l’un ni l’autre ?","type":"categories","categories":[{"id":"c0","texte":"Discours direct"},{"id":"c1","texte":"Discours indirect"},{"id":"c2","texte":"Discours indirect libre"}],"items":[{"id":"i0","texte":"Quelle chance, après tout, d’avoir une femme si élégante !"},{"id":"i1","texte":"Le mari dit qu’il faisait froid ce matin-là."},{"id":"i2","texte":"Il faisait froid, bien sûr, mais jamais elle ne sortirait sans son manteau !"},{"id":"i3","texte":"Elle répondit qu’elle ne sortirait pas sans son manteau."},{"id":"i4","texte":"« Il fait froid, ce matin », dit le mari."}]},{"enonce":"Touche le mot qui **retourne le sens** de toute la nouvelle : la chute.","aide":"Cherche dans les toutes dernières lignes, sur l’étiquette.","type":"zone","document":"manteau","multiple":false},{"enonce":"Que **met en accusation** cette chute ?","aide":"Dans La Parure aussi, un bijou faux accuse…","type":"choix","options":[{"id":"a","texte":"Le goût du village pour les fourrures très chères"},{"id":"b","texte":"La méchanceté du voisin, qui voulait la ridiculiser"},{"id":"c","texte":"La paresse du mari, qui refuse d’acheter mieux"},{"id":"d","texte":"La vanité de Madame Lefort : son luxe n’était qu’un faux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27","m31"]},"explication":"Des gants **reprisés** et des bottines **éculées** : un détail vrai suffit à dire la place sociale."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c2","i3":"c1","i4":"c0"}},"explication":"Au **direct** : guillemets. À l’**indirect** : verbe introducteur + « que ». Au **discours indirect libre** : les pensées passent dans le récit sans guillemets ni verbe introducteur."},{"cle":{"type":"zone","ids":["m106"]},"explication":"Le mot **lapin** transforme le manteau de luxe en faux : c’est la chute."},{"cle":{"type":"choix","ids":["d"]},"explication":"Comme dans La Parure, la chute **accuse la vanité** : le luxe n’était qu’une apparence."}]$ex$::jsonb),
  ('30417519-e1db-5a1c-a8ec-25d7f3771ef0'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Étienne descend à la fosse","competence":"analyser-texte","situation":"Un élève a rédigé une scène de roman et hésite : est-elle réaliste ou naturaliste ? Compare avec le tableau des deux courants et conclus.","documents":[{"id":"courants","type":"tableau","titre":"Deux courants","colonnes":["Le courant","Sa thèse"],"lignes":[["Le réalisme","Décrire le personnage dans son milieu"],["Le naturalisme","Le personnage est le produit de son hérédité et de son milieu"]],"enteteLignes":false},{"id":"mine","type":"texte","genre":"recit","titre":"Le coron","blocs":["Étienne avait douze ans quand il descendit à la fosse, comme son père, mort de la poussière, et comme son frère aîné.","Dans le coron, personne ne s’était jamais demandé s’il pouvait faire autre chose : la mine vous prenait à la naissance et ne vous lâchait qu’au cimetière."],"source":"Extrait écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois mots** qui désignent le **milieu** d’Étienne.","aide":"Le lieu de travail, le lieu de vie et l’industrie.","type":"zone","document":"mine","multiple":true},{"enonce":"Dans le tableau, touche la case de la thèse que **ce texte illustre**.","aide":"Le père mort de la poussière, le frère, la mine : ce destin est-il décrit ou expliqué ?","type":"zone","document":"courants","multiple":false},{"enonce":"Range chaque idée dans le courant qui la défend.","aide":"Le naturalisme ajoute une prétention scientifique.","type":"categories","categories":[{"id":"c0","texte":"Réalisme"},{"id":"c1","texte":"Naturalisme"}],"items":[{"id":"i0","texte":"Se réclamer d’une méthode dite expérimentale"},{"id":"i1","texte":"Accuser la société sans se réclamer d’une science"},{"id":"i2","texte":"Le personnage est le produit de son hérédité et de son milieu"},{"id":"i3","texte":"Décrire le personnage dans son milieu"}]},{"enonce":"Pourquoi Maupassant reste-t-il plus proche du réalisme que du naturalisme ?","aide":"Pense à ce qu’il ne revendique jamais, contrairement à Zola.","type":"choix","options":[{"id":"a","texte":"Il n’écrit que des romans et jamais de nouvelles"},{"id":"b","texte":"Il admire la noblesse et ignore tout milieu populaire"},{"id":"c","texte":"Il accuse la société sans se réclamer d’une science"},{"id":"d","texte":"Il refuse de décrire la réalité sociale de son temps"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m24","m38"]},"explication":"La **fosse**, le **coron** et la **mine** forment le milieu qui enferme le personnage."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le destin d’Étienne vient de sa famille et de son milieu : c’est la thèse du **naturalisme**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Le **réalisme** décrit le personnage dans son milieu ; le **naturalisme** y ajoute l’hérédité et une méthode expérimentale (Zola)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il **accuse la société sans se réclamer d’une science** : c’est ce qui le tient plus près du réalisme."}]$ex$::jsonb),
  ('f6d6fbe4-1685-5f4f-903b-d158ed5f55ea'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La fiche de lecture de L’Étranger","competence":"analyser-document","situation":"Avant de lire L’Étranger, Anaïs a préparé une fiche de lecture et un petit texte pour sentir le style du livre. Aide-la à repérer l’essentiel.","documents":[{"id":"fiche","type":"tableau","titre":"Fiche de lecture","colonnes":["Rubrique","Information"],"lignes":[["Auteur","Albert Camus"],["Titre","L’Étranger"],["Parution","1942"],["Narrateur","Meursault, employé à Alger"],["Narration","À la première personne"],["Temps verbal dominant","Le passé composé"],["Cycle","Le cycle de l’absurde"]],"enteteLignes":false},{"id":"voix","type":"texte","genre":"recit","titre":"Un petit texte pour sentir le style","blocs":["Hier, le facteur est passé. J’ai mangé à midi. Puis je suis allé à la plage. Il faisait chaud."],"source":"Texte écrit pour l’exercice, à la manière d’une « voix blanche »"}],"questions":[{"enonce":"Touche la case qui donne le **temps verbal dominant** du roman.","aide":"Regarde la rubrique « Temps verbal ».","type":"zone","document":"fiche","multiple":false},{"enonce":"Touche les **trois participes passés** qui forment des passés composés.","aide":"Cherche « est … », « ai … », « suis … ».","type":"zone","document":"voix","multiple":true},{"enonce":"Quel effet produit cette écriture courte, sans image ni explication ?","aide":"Pense à la « voix blanche ».","type":"choix","options":[{"id":"a","texte":"Une émotion forte, car le narrateur dit ce qu’il ressent"},{"id":"b","texte":"Une poésie riche en métaphores et en comparaisons"},{"id":"c","texte":"Un malaise : le narrateur dit tout et n’explique rien"},{"id":"d","texte":"Un suspense d’aventure fondé sur de longues descriptions"}],"multiple":false},{"enonce":"Remets dans l’ordre les grandes étapes du roman.","aide":"Le roman s’ouvre sur un deuil et se ferme sur un tribunal.","type":"ordre","items":[{"id":"a","texte":"La liaison avec Marie et la vie ordinaire"},{"id":"b","texte":"Le procès et la condamnation à mort"},{"id":"c","texte":"La mort de la mère et l’enterrement"},{"id":"d","texte":"Le meurtre sur la plage"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r5c1"]},"explication":"Le roman est écrit au **passé composé**, qui donne aux faits l’air de constats."},{"cle":{"type":"zone","ids":["m4","m7","m13"]},"explication":"**passé**, **mangé**, **allé** : trois passés composés. « Faisait » est à l’imparfait."},{"cle":{"type":"choix","ids":["c"]},"explication":"La **voix blanche** produit un **malaise** : rien n’est interprété pour le lecteur."},{"cle":{"type":"ordre","ids":["c","a","d","b"]},"explication":"Enterrement, vie ordinaire avec Marie, **meurtre sur la plage**, puis **procès** et condamnation."}]$ex$::jsonb),
