   $ex${"titre":"Le dimanche chez la grand-mère","competence":"analyser-texte","situation":"Une lycéenne s’exerce à écrire son enfance dans une langue simple, sans effets, comme certains auteurs contemporains. Étudie son texte : qui parle, et à quel moment ?","documents":[{"id":"dimanche","type":"texte","genre":"recit","titre":"Le dimanche","blocs":["Le dimanche, nous allions chez ma grand-mère. Mon père portait sa veste des mariages. On mangeait du lapin.","Aujourd’hui, en écrivant, je sais que ce lapin coûtait cher et que ma mère comptait. À l’époque, je croyais seulement que c’était dimanche."],"source":"Texte écrit pour l’exercice, dans une langue volontairement plate"}],"questions":[{"enonce":"Touche les **deux mots** qui signalent le « je » **qui écrit** aujourd’hui.","aide":"Un adverbe de temps, un verbe au présent.","type":"zone","document":"dimanche","multiple":true},{"enonce":"Range chaque phrase selon le « je » qui parle.","aide":"L’enfant ignore ; l’adulte qui écrit sait.","type":"categories","categories":[{"id":"c0","texte":"Le « je » qui a vécu"},{"id":"c1","texte":"Le « je » qui écrit"}],"items":[{"id":"i0","texte":"Je croyais seulement que c’était dimanche."},{"id":"i1","texte":"Je sais que ce lapin coûtait cher."},{"id":"i2","texte":"Aujourd’hui, en écrivant, je comprends ma mère."},{"id":"i3","texte":"Nous allions chez ma grand-mère."}]},{"enonce":"Pourquoi « allions », « portait », « mangeait » sont-ils à l’imparfait ?","aide":"Le texte commence par « Le dimanche » : tous les dimanches ?","type":"choix","options":[{"id":"a","texte":"Pour annoncer ce qui va se passer plus tard"},{"id":"b","texte":"Pour exprimer le bilan d’une vie déjà achevée"},{"id":"c","texte":"Pour dire l’habitude, la répétition des dimanches"},{"id":"d","texte":"Pour dire un événement unique et très précis"}],"multiple":false},{"enonce":"Complète la phrase du cours sur le style.","aide":"Pas de belles images : un choix de style qui a un sens social.","type":"trous","segments":[