  ('ddd36c06-79ee-5afe-9c04-f57c9b28c204'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La tour 4","competence":"analyser-texte","situation":"Dans un recueil de nouvelles de lycéens, trois scènes se passent dans une cité. Un auteur veut-il la montrer de l’intérieur, ou de loin ? Repère les procédés.","documents":[{"id":"tour","type":"texte","genre":"recit","titre":"La tour 4","blocs":["Nadia habite la tour 4 du quartier des Glycines. De sa fenêtre, elle voit le périphérique qui gronde jour et nuit et, loin derrière, les toits du centre.","Quand l’ambulance entra, toute la cité se mit aux fenêtres. Un gamin cria : « T’as vu les keufs derrière ? »","Un journaliste passait en voiture, vitres fermées. Il murmura à son photographe que « tout ça » faisait peur, puis il accéléra."],"source":"Nouvelle écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot employé par **métonymie** pour désigner les habitants.","aide":"Le lieu pour ceux qui y vivent.","type":"zone","document":"tour","multiple":false},{"enonce":"Touche le mot de **verlan** qui fait entendre une langue réelle.","aide":"Le gamin désigne ainsi les policiers.","type":"zone","document":"tour","multiple":false},{"enonce":"Depuis où le troisième paragraphe regarde-t-il la cité ?","aide":"Le journaliste a les vitres fermées et il accélère.","type":"choix","options":[{"id":"a","texte":"De l’intérieur, depuis la fenêtre d’une habitante"},{"id":"b","texte":"Depuis le toit de la tour, avec une vue d’ensemble"},{"id":"c","texte":"Depuis le centre-ville, loin du périphérique"},{"id":"d","texte":"De l’extérieur, depuis une voiture qui passe sans s’arrêter"}],"multiple":false},{"enonce":"Relie chaque procédé à ce qu’il révèle.","aide":"Chaque procédé a son effet dans le tableau du cours.","type":"association","gauche":[{"id":"g0","texte":"La métonymie"},{"id":"g1","texte":"L’opposition centre / périphérie"},{"id":"g2","texte":"L’oralité"},{"id":"g3","texte":"Le champ lexical de l’espace"}],"droite":[{"id":"d0","texte":"Béton, cage d’escalier, périph"},{"id":"d1","texte":"Une hiérarchie spatiale"},{"id":"d2","texte":"Une langue réelle, discours direct et argot"},{"id":"d3","texte":"« La cité » pour ses habitants"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34"]},"explication":"**Cité** désigne ici ses habitants, qui se mettent aux fenêtres : c’est une métonymie."},{"cle":{"type":"zone","ids":["m46"]},"explication":"**Keufs** est du verlan (« flics ») : l’oralité fait entendre la parole du quartier."},{"cle":{"type":"choix","ids":["d"]},"explication":"La cité est vue **de l’extérieur**, depuis une voiture qui passe : la focalisation produit la peur et la mise à distance."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"Métonymie : **la cité** pour ses habitants ; opposition : une **hiérarchie spatiale** ; oralité : une **langue réelle** ; champ lexical : béton, escalier, périph."}]$ex$::jsonb),
  ('ddd36c06-79ee-5afe-9c04-f57c9b28c204'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La même cité, deux regards","competence":"argumenter","situation":"Deux élèves ont décrit la même cité : l’un en visiteur de passage, l’autre en habitante. Compare leurs textes et demande-toi, à chaque phrase : qui parle ?","documents":[{"id":"visiteur","type":"texte","genre":"recit","titre":"Version A : un visiteur","blocs":["En traversant la cité, on se croirait sur une autre planète : des tours grises à perte de vue, des ombres qui rôdent au pied des immeubles, pas un arbre. On accélère, on verrouille les portières, on repart soulagé."],"source":"Texte écrit pour l’exercice"},{"id":"habitante","type":"texte","genre":"recit","titre":"Version B : une habitante","blocs":["Chez nous, le dimanche, l’escalier sent le couscous de Mme Diallo et le gâteau de Mme Lopes. Au pied de la tour, les gamins jouent au foot jusqu’à la nuit, et personne ne ferme à clé."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Dans la version A, touche les **deux mots** qui rendent la cité exotique ou inquiétante.","aide":"Une autre planète, des silhouettes menaçantes.","type":"zone","document":"visiteur","multiple":true},{"enonce":"Range chaque phrase selon le regard qu’elle porte sur la cité.","aide":"Qui connaît les habitants par leur nom ?","type":"categories","categories":[{"id":"c0","texte":"Regard de l’extérieur"},{"id":"c1","texte":"Regard de l’intérieur"}],"items":[{"id":"i0","texte":"On accélère, on verrouille les portières."},{"id":"i1","texte":"Des ombres qui rôdent au pied des immeubles."},{"id":"i2","texte":"Les gamins jouent au foot jusqu’à la nuit."},{"id":"i3","texte":"L’escalier sent le couscous de Mme Diallo."}]},{"enonce":"Quel effet produit la version B sur le lecteur ?","aide":"Mme Diallo, Mme Lopes, les gamins : des personnes, pas un décor.","type":"choix","options":[{"id":"a","texte":"De la peur : la cité est décrite comme dangereuse"},{"id":"b","texte":"De l’indifférence : il ne s’y passe rien d’important"},{"id":"c","texte":"De la sympathie : on entend la vie ordinaire du quartier"},{"id":"d","texte":"De la colère : l’autrice accuse directement la police"}],"multiple":false},{"enonce":"Complète la conclusion du cours.","aide":"Les deux textes décrivent la même cité…","type":"trous","segments":["Une représentation n’est jamais ",0," : elle produit de la sympathie, de la peur ou de l’indifférence."],"banque":["inutile","neutre","fausse","ancienne"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m21"]},"explication":"**Planète** et **rôdent** mettent la cité à distance : on la décrit comme un monde étranger et menaçant."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"De l’extérieur, on voit des menaces ; de l’**intérieur**, on connaît les noms, les odeurs, les jeux."},{"cle":{"type":"choix","ids":["c"]},"explication":"La version B donne des noms et des gestes familiers : elle produit de la **sympathie**."},{"cle":{"type":"trous","trous":[["neutre"]]},"affichage":"neutre","explication":"Une représentation n’est jamais **neutre** : étudier les écritures urbaines, c’est se demander qui fabrique les images sociales."}]$ex$::jsonb),
  ('15f19fce-8caf-52b0-a5f5-3e84c4e3f175'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un retard au lycée","competence":"analyser-texte","situation":"Pour le cours de théâtre, la classe a écrit une petite scène. Avant de la jouer, il faut distinguer ce qui se dit de ce qui se joue, et compter les scènes d’une autre pièce.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Une salle de classe","blocs":[{"didascalie":"Une salle de classe, vide. Léo entre en courant. Nina range ses affaires."},{"personnage":"Léo","replique":"Tu as vu l’heure ? On est en retard !"},{"personnage":"Nina","replique":"Du calme. Le prof est malade."},{"didascalie":"Nina, à part, au public : elle sourit."},{"personnage":"Nina","replique":"Il n’est pas malade du tout : j’ai caché ses clés."}],"source":"Texte écrit pour l’exercice"},{"id":"entrees","type":"tableau","titre":"Qui est sur scène ? (extrait d’une autre pièce)","colonnes":["Moment","Sur scène"],"lignes":[["Au lever de rideau","Léo, Nina"],["Théo entre","Léo, Nina, Théo"],["Léo sort","Nina, Théo"],["Théo sort","Nina"]],"enteteLignes":false,"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Range chaque ligne du texte selon sa nature.","aide":"Ce qui est dit par un personnage, ou ce qui est indiqué pour la scène ?","type":"categories","categories":[{"id":"c0","texte":"Didascalie"},{"id":"c1","texte":"Réplique"}],"items":[{"id":"i0","texte":"Du calme. Le prof est malade."},{"id":"i1","texte":"Nina range ses affaires."},{"id":"i2","texte":"Léo entre en courant."},{"id":"i3","texte":"Tu as vu l’heure ? On est en retard !"}]},{"enonce":"Touche les **deux mots** de la didascalie qui annoncent un **aparté**.","aide":"Nina parle au public, sans que Léo l’entende.","type":"zone","document":"scene","multiple":true},{"enonce":"Dans une pièce classique, une scène change dès qu’un personnage entre ou sort. Combien de **scènes** compte l’extrait du tableau ?","aide":"Compte chaque ligne : chaque changement de personnages sur scène ouvre une scène.","type":"nombre","unite":"scènes"}]}$