  ('15f19fce-8caf-52b0-a5f5-3e84c4e3f175'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le Fil rouge, comédie en trois actes","competence":"analyser-document","situation":"Le programme de salle d’une comédie résume l’intrigue en cinq paragraphes. À toi de reconnaître le rôle de chacun dans la construction de la pièce.","documents":[{"id":"resume","type":"texte","genre":"article","titre":"Le Fil rouge : le résumé","blocs":["Chez les Vallier, on prépare le mariage de Camille avec Armand, un riche voisin. Le valet Pascal apprend au public que la famille est ruinée.","Camille, qui aime en secret le jeune libraire Oscar, refuse ce mariage : le conflit est posé.","Pascal imagine plusieurs ruses pour retarder la noce ; chacune échoue et complique l’intrigue.","Soudain, Armand avoue qu’il est lui-même sans un sou et qu’il courtisait Camille pour sa dot.","Les deux familles se réconcilient et Camille épouse Oscar."],"source":"Résumé imaginé pour l’exercice"}],"questions":[{"enonce":"Relie chaque paragraphe à son rôle dans la pièce.","aide":"Informer, installer le conflit, le relancer, le renverser, le résoudre.","type":"association","gauche":[{"id":"g0","texte":"Paragraphe 1"},{"id":"g1","texte":"Paragraphe 2"},{"id":"g2","texte":"Paragraphe 3"},{"id":"g3","texte":"Paragraphe 4"},{"id":"g4","texte":"Paragraphe 5"}],"droite":[{"id":"d0","texte":"Les péripéties"},{"id":"d1","texte":"Le dénouement"},{"id":"d2","texte":"Le coup de théâtre"},{"id":"d3","texte":"L’exposition"},{"id":"d4","texte":"Le nœud"}]},{"enonce":"Touche le mot qui annonce le **renversement brutal** de la situation.","aide":"Un adverbe qui marque la surprise, au début du paragraphe 4.","type":"zone","document":"resume","multiple":false},{"enonce":"Pourquoi le valet Pascal « apprend-il au public » que la famille est ruinée ?","aide":"Le rôle de l’exposition est dit dans le cours.","type":"choix","options":[{"id":"a","texte":"Pour informer le spectateur de la situation : c’est l’exposition"},{"id":"b","texte":"Pour résoudre le conflit en révélant le secret de la famille"},{"id":"c","texte":"Pour lancer un coup de théâtre qui renverse brutalement la pièce"},{"id":"d","texte":"Pour interrompre l’action par un monologue sans rapport avec l’intrigue"}],"multiple":false},{"enonce":"Range chaque situation selon le registre qu’elle illustre.","aide":"Rire, fatalité, émotion, sentiments.","type":"categories","categories":[{"id":"c0","texte":"Comique"},{"id":"c1","texte":"Tragique"},{"id":"c2","texte":"Pathétique"},{"id":"c3","texte":"Lyrique"}],"items":[{"id":"i0","texte":"Un valet glisse et renverse tout le dîner."},{"id":"i1","texte":"Un jeune homme chante sa joie d’aimer sous une fenêtre."},{"id":"i2","texte":"Un roi comprend qu’il ne peut échapper à son destin."},{"id":"i3","texte":"Une mère en larmes supplie qu’on lui rende son enfant."}]}]}$ex$::jsonb,
