egories":[{"id":"c0","texte":"Théâtre classique"},{"id":"c1","texte":"Drame romantique"}],"items":[{"id":"i0","texte":"Place du hasard et de l’ironie"},{"id":"i1","texte":"Séparation stricte des genres"},{"id":"i2","texte":"Respect des trois unités"},{"id":"i3","texte":"Nécessité tragique"},{"id":"i4","texte":"Mélange de fantaisie et de tragédie"}]}]}$ex$::jsonb,
