   $ex${"titre":"Sur le toit","competence":"analyser-texte","situation":"Pour son oral, Maëlle a écrit un monologue à la manière de Koltès : un homme, un toit, le soleil. Lis-le avec un tableau de ce que Koltès refuse et de ce qu’il donne à la place.","documents":[{"id":"toit","type":"texte","genre":"theatre","titre":"Un monologue","blocs":[{"didascalie":"Un toit, en plein soleil. L’Homme est debout, au bord."},{"personnage":"L’Homme","replique":"Le soleil ne me regarde pas. C’est moi qui le regarde, et il ne dit rien. En bas, ils courent. Ils croient que courir, c’est comprendre. Moi, je ne cours pas : je passe."}],"source":"Monologue écrit pour l’exercice, à la manière de Koltès"},{"id":"refus","type":"tableau","titre":"Ce que la pièce refuse, ce qu’elle donne","colonnes":["Ce que Koltès refuse","Ce qu’il donne à la place"],"lignes":[["Un mobile","?"],["Une enfance analysée","?"],["Une leçon","?"]],"enteteLignes":false}],"questions":[{"enonce":"Touche le mot qui fait entrer ce monologue dans le **mythe** (comme les monologues de Zucco).","aide":"Un astre, au début de la réplique.","type":"zone","document":"toit","multiple":false},{"enonce":"Relie chaque refus de Koltès à ce qu’il donne à la place.","aide":"Il ne demande ni compréhension ni pardon.","type":"association","gauche":[{"id":"g0","texte":"Un mobile"},{"id":"g1","texte":"Une enfance analysée"},{"id":"g2","texte":"Une leçon"}],"droite":[{"id":"d0","texte":"Un regard"},{"id":"d1","texte":"Rien"},{"id":"d2","texte":"Une énergie qui passe et détruit"}]},{"enonce":"Pourquoi désigner les personnages par une fonction (la Gamine, la Mère, la Dame) ?","aide":"Pense à Œdipe ou à Médée : des figures plutôt que des portraits.","type":"choix","options":[{"id":"a","texte":"Cela les rapproche des figures mythiques"},{"id":"b","texte":"Cela prouve qu’ils n’ont aucun rôle dans la pièce"},{"id":"c","texte":"Cela cache leur identité aux spectateurs de la salle"},{"id":"d","texte":"Cela les rend plus drôles que des personnages nommés"}],"multiple":false},{"enonce":"Complète la phrase du cours.","aide":"Plus de dieux ni de rois : une force qui pèse sur le héros.","type":"trous","segments":["Dans la tragédie moderne, la fatalité prend la forme d’un ",0," social, d’une famille, d’une ville."],"banque":["dieu","rêve","déterminisme","oracle"]}]}$ex$::jsonb,
