  ('f38a5f57-b6f1-5392-8a2e-8cfc29d582d8'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Peut-on mettre un criminel sur scène ?","competence":"argumenter","situation":"Au lycée, un débat sur *Roberto Zucco* est affiché dans le hall. Quatre élèves ont répondu à la question. À toi de départager objections et réponses de Koltès.","documents":[{"id":"debat","type":"fiche","modele":"affiche","entete":"Débat","sousTitre":"Peut-on mettre un criminel sur scène ?","emoji":"💬","teinte":"turquoise","lignes":[{"texte":"Inès","valeur":"Un portrait donne envie de plaindre le criminel.","id":"z1"},{"texte":"Malik","valeur":"Il n’est pas un portrait : c’est une figure.","id":"z2"},{"texte":"Chloé","valeur":"Mettre un tueur sur scène, c’est lui faire de la publicité.","id":"z3"},{"texte":"Sam","valeur":"La pièce vise la violence d’une société entière.","id":"z4"}],"pied":"Réponses imaginées pour l’exercice"},{"id":"programme","type":"texte","genre":"article","titre":"Extrait du programme de salle","blocs":["Roberto Zucco s’inspire d’un fait divers, mais Koltès n’en fait ni un portrait ni un procès : le personnage traverse quinze tableaux comme une énergie qui passe et détruit, sans qu’on explique jamais ses mobiles."],"source":"Programme de salle imaginé pour l’exercice"}],"questions":[{"enonce":"Classe chaque argument de l’affiche.","aide":"Koltès défend la figure et la société, pas le portrait.","type":"categories","categories":[{"id":"c0","texte":"Objection au spectacle"},{"id":"c1","texte":"Réponse de Koltès"}],"items":[{"id":"i0","texte":"Il n’est pas un portrait : c’est une figure."},{"id":"i1","texte":"Un portrait donne envie de plaindre le criminel."},{"id":"i2","texte":"La pièce vise la violence d’une société entière."},{"id":"i3","texte":"Mettre un tueur sur scène, c’est lui faire de la publicité."}]},{"enonce":"Touche ce que Koltès **refuse d’expliquer** à propos de son personnage.","aide":"Pas de psychologie : pourquoi agit-il ?","type":"zone","document":"programme","multiple":false},{"enonce":"Pourquoi comparer Zucco à Œdipe ou à Médée ?","aide":"Koltès répond à ceux qui l’accusent de glorifier un criminel.","type":"choix","options":[{"id":"a","texte":"Comme eux, il est raconté par un messager"},{"id":"b","texte":"Comme eux, il est condamné par les dieux grecs"},{"id":"c","texte":"Comme eux, il est un roi tombé du pouvoir"},{"id":"d","texte":"Comme eux, c’est une figure et non un portrait"}],"multiple":false},{"enonce":"Que vise la pièce, selon Koltès ?","aide":"L’objectif n’est pas l’individu.","type":"choix","options":[{"id":"a","texte":"Une satire des journalistes qui racontent les faits divers"},{"id":"b","texte":"La violence d’une société entière, plus que la folie d’un homme"},{"id":"c","texte":"La défense d’un criminel réel face à une justice injuste"},{"id":"d","texte":"Une enquête policière sur la cavale d’un fugitif célèbre"}],"multiple":false},{"enonce":"Complète la conclusion.","aide":"Un chemin, de tableau en tableau.","type":"trous","segments":["La tragédie moderne se passe de dieux et de rois : le héros n’a plus de grandeur, seulement une ",0," qu’il ne maîtrise pas."],"banque":["victoire","trajectoire","armée","couronne"]}]}$ex$::jsonb,
