   $ex${"titre":"Le récit du messager","competence":"analyser-texte","situation":"Dans une pièce classique inventée pour l’exercice, un messager vient annoncer la mort du roi. Observe comment elle est dite, puis situe ce traitement dans le tableau des quatre époques.","documents":[{"id":"messager","type":"texte","genre":"theatre","titre":"Le récit","blocs":[{"didascalie":"Une salle du palais. Un messager entre, hors d’haleine."},{"personnage":"Le Messager","replique":"Seigneur, j’ai tout vu. Le roi marchait vers la rivière quand le pont a cédé. Il a lutté longtemps contre le courant ; puis les eaux se sont refermées. Je n’ai pu que revenir vous le dire."}],"source":"Texte écrit pour l’exercice"},{"id":"epoques","type":"tableau","titre":"Quatre époques","colonnes":["L’époque","Son moyen"],"lignes":[["Antiquité et classicisme","Le récit du messager, le hors-scène"],["Théâtre élisabéthain et romantisme","La mort sur scène"],["XXe siècle","L’attente remplace l’événement"],["Aujourd’hui","Témoignage, chœur, liste de noms"]],"enteteLignes":false}],"questions":[{"enonce":"Touche le verbe qui prouve que le messager a été **témoin** de la scène.","aide":"Il n’a pas entendu dire : il…","type":"zone","document":"messager","multiple":false},{"enonce":"Dans le tableau, touche la case qui décrit **le moyen** utilisé par ce passage.","aide":"Un messager qui raconte, une mort hors scène.","type":"zone","document":"epoques","multiple":false},{"enonce":"Pourquoi la tragédie classique fait-elle raconter la mort plutôt que la montrer ?","aide":"Une des règles du XVIIe siècle : bienséance.","type":"choix","options":[{"id":"a","texte":"Les acteurs ne savaient pas jouer la mort de façon crédible"},{"id":"b","texte":"Le roi interdisait toute pièce où quelqu’un mourrait"},{"id":"c","texte":"La bienséance interdit de montrer la mort et la violence"},{"id":"d","texte":"Le public de l’époque préférait les histoires courtes"}],"multiple":false},{"enonce":"Relie chaque époque au traitement de la mort qu’elle privilégie.","aide":"Un verbe par époque : raconter, montrer, suspendre, documenter.","type":"association","gauche":[{"id":"g0","texte":"Antiquité et classicisme"},{"id":"g1","texte":"Théâtre élisabéthain et romantisme"},{"id":"g2","texte":"XXe siècle"},{"id":"g3","texte":"Aujourd’hui"}],"droite":[{"id":"d0","texte":"Suspendre"},{"id":"d1","texte":"Documenter"},{"id":"d2","texte":"Montrer"},{"id":"d3","texte":"Raconter"}]}]}$ex$::jsonb,
