  ('0e59af0a-263a-5ec1-afa2-3aeafdd00f7f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Rose et Léon attendent","competence":"analyser-texte","situation":"Dans un petit théâtre de poche, on joue une saynète où deux vieillards attendent la mort. L’auteur est un élève : la scène est inventée pour l’exercice, dans l’esprit du théâtre de l’absurde.","documents":[{"id":"attente","type":"texte","genre":"theatre","titre":"L’attente","blocs":[{"didascalie":"Une cuisine. Deux vieillards, Rose et Léon, devant une table. Un téléphone qui ne sonne pas."},{"personnage":"Rose","replique":"Il paraît qu’on doit s’y préparer."},{"personnage":"Léon","replique":"À quoi ?"},{"personnage":"Rose","replique":"À ce qui vient."},{"personnage":"Léon","replique":"Ça vient depuis hier."},{"personnage":"Rose","replique":"Depuis toujours, Léon."},{"personnage":"Léon","replique":"Alors on attend."},{"didascalie":"Ils attendent. La lumière baisse très lentement. Il ne reste bientôt sur la table que le chapeau de Léon. Silence."}],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux procédés de mise en scène** qui suspendent le temps à la fin.","aide":"Ce qui baisse et ce qui tombe, dans la dernière didascalie.","type":"zone","document":"attente","multiple":true},{"enonce":"Touche l’**objet qui reste** sur scène.","aide":"Il appartient à l’un des deux personnages.","type":"zone","document":"attente","multiple":false},{"enonce":"Relie chaque auteur ou courant à ce qu’il fait de la mort.","aide":"Attente, cérémonie lente, durée.","type":"association","gauche":[{"id":"g0","texte":"Beckett"},{"id":"g1","texte":"Ionesco, Le roi se meurt"},{"id":"g2","texte":"Le théâtre de l’absurde"}],"droite":[{"id":"d0","texte":"On n’en finit pas de mourir : l’attente est le sujet"},{"id":"d1","texte":"La mort devient une durée plutôt qu’un coup de théâtre"},{"id":"d2","texte":"Une cérémonie lente et absurde"}]},{"enonce":"Que devient la mort dans cette saynète ?","aide":"Rien ne se passe, et pourtant tout se joue.","type":"choix","options":[{"id":"a","texte":"Un récit de messager qui raconte ce qu’il a vu"},{"id":"b","texte":"Une attente : elle est une durée, non un événement"},{"id":"c","texte":"Une scène spectaculaire qui jonche le plateau de corps"},{"id":"d","texte":"Un coup de théâtre qui renverse brutalement la pièce"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m43","m59"]},"explication":"La **lumière** qui baisse et le **silence** suspendent la scène : la mort devient durée."},{"cle":{"type":"zone","ids":["m56"]},"explication":"Le **chapeau** : l’objet qui reste dit l’absence sans montrer la mort."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**Beckett** : l’attente ; **Ionesco** : une cérémonie lente et absurde ; l’**absurde** transforme la mort en durée."},{"cle":{"type":"choix","ids":["b"]},"explication":"Au XXe siècle, la mort est **suspendue** : on attend, on ne la voit pas arriver."}]$ex$::jsonb),
