":"association","gauche":[{"id":"g0","texte":"Extrait 1"},{"id":"g1","texte":"Extrait 2"},{"id":"g2","texte":"Extrait 3"},{"id":"g3","texte":"Extrait 4"},{"id":"g4","texte":"Extrait 5"}],"droite":[{"id":"d0","texte":"Marivaux"},{"id":"d1","texte":"Le metteur en scène devenu auteur"},{"id":"d2","texte":"Le départ du réel"},{"id":"d3","texte":"Le drame bourgeois"},{"id":"d4","texte":"Corneille"}]},{"enonce":"Dans le tableau, touche la case qui regroupe les auteurs du siècle de la **bataille d’Hernani** (1830).","aide":"1830, c’est quel siècle ?","type":"zone","document":"siecles","multiple":false},{"enonce":"Complète la phrase du cours.","aide":"Il interprète le texte : décor, lumière, costumes, jeu.","type":"trous","segments":["Au XXe siècle, le ",0," devient un auteur à part entière, et le texte n’est plus la seule source du spectacle."],"banque":["décorateur","spectateur","souffleur","metteur en scène"]}]}$ex$::jsonb,
