  ('0b344c8a-3461-5331-bcbc-51fae81a3ed4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois mots grecs, deux cas","competence":"manier-langue","situation":"Théa ouvre sa première page de grec : un petit tableau avec trois mots de la langue d’Athènes. Avant de traduire quoi que ce soit, elle doit repérer leurs formes.","documents":[{"id":"tab","type":"tableau","titre":"Trois noms au nominatif et au génitif","colonnes":["Déclinaison","Nominatif","Génitif","Sens"],"lignes":[["1re","ἡ τιμή","τῆς τιμῆς","l’honneur"],["2e","ὁ λόγος","τοῦ λόγου","la parole"],["2e (neutre)","τὸ δῶρον","τοῦ δώρου","le don"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le nominatif du mot qui veut dire « le don ».","aide":"Regarde la colonne « Sens », puis lis la colonne « Nominatif » sur la même ligne.","type":"zone","document":"tab","multiple":false},{"enonce":"Touche les deux génitifs du tableau qui se terminent par la même finale « -ου ».","aide":"Les deux mots sont de la 2e déclinaison.","type":"zone","document":"tab","multiple":true},{"enonce":"Associe chaque cas à sa fonction principale.","aide":"Le génitif répond à la question « de qui ? ».","type":"association","gauche":[{"id":"g0","texte":"nominatif"},{"id":"g1","texte":"accusatif"},{"id":"g2","texte":"génitif"},{"id":"g3","texte":"datif"}],"droite":[{"id":"d0","texte":"sujet du verbe"},{"id":"d1","texte":"complément d’objet direct"},{"id":"d2","texte":"complément d’objet indirect"},{"id":"d3","texte":"complément du nom"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le don se dit à la troisième ligne ; son **nominatif** est la forme de la colonne « Nominatif », celle qui sert de sujet."},{"cle":{"type":"zone","ids":["r1c2","r2c2"]},"explication":"Les génitifs de **la parole** et de **le don** finissent tous deux par -ου : c’est la marque du génitif singulier de la 2e déclinaison."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"Le **nominatif** donne le sujet, l’**accusatif** le COD, le **génitif** le complément du nom et le **datif** le COI."}]$ex$::jsonb),
  ('0b344c8a-3461-5331-bcbc-51fae81a3ed4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le citoyen, la parole : qui fait quoi ?","competence":"comprendre-langue","situation":"Dans son cahier, Théa lit deux phrases grecques écrites pour s’entraîner. Elle n’a pas le droit de traduire dans l’ordre des mots : elle doit d’abord trouver les cas.","documents":[{"id":"phrases","type":"texte","genre":"recit","titre":"Deux phrases à analyser","auteur":"Phrases écrites pour l’exercice","blocs":["ὁ πολίτης τὸ δῶρον λαμβάνει.","τὸν πολίτην ὁ λόγος τέρπει."]},{"id":"voc","type":"tableau","titre":"Vocabulaire","colonnes":["Mot","Sens"],"lignes":[["ὁ πολίτης","le citoyen"],["ὁ λόγος","la parole"],["τὸ δῶρον","le don"],["λαμβάνει","il reçoit"],["τέρπει","il réjouit"]]}],"questions":[{"enonce":"Dans la phrase 2, touche le sujet du verbe.","aide":"Le sujet est au nominatif : son article n’a pas de -ν final.","type":"zone","document":"phrases","multiple":false},{"enonce":"Dans la phrase 2, touche le complément d’objet direct.","aide":"Le COD est à l’accusatif : l’article se termine par -ν.","type":"zone","document":"phrases","multiple":false},{"enonce":"Complète l’analyse de la phrase 2.","aide":"Le sujet est toujours au nominatif.","type":"trous","segments":["Dans la phrase 2, « le citoyen » est à l’",0," et « la parole » au ",1,"."],"banque":["génitif","nominatif","accusatif","datif"]},{"enonce":"Dans la phrase 1, comment sait-on que « le don » n’est pas le sujet ?","aide":"Relis la règle du neutre dans le cours.","type":"choix","options":[{"id":"a","texte":"Sa forme ne dit rien (nominatif = accusatif au neutre) ; le sens tranche"},{"id":"b","texte":"Un nom neutre ne peut jamais être sujet d’un verbe en grec"},{"id":"c","texte":"Il est en deuxième position, et l’ordre des mots fixe la fonction"},{"id":"d","texte":"Sa terminaison est celle de l’accusatif, absente du nominatif"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"Le sujet est **« la parole »** : il est au nominatif, précédé de l’article du nominatif. Dans la phrase 2, c’est la parole qui réjouit."},{"cle":{"type":"zone","ids":["m6"]},"explication":"Le COD est **« le citoyen »**, à l’accusatif : l’ordre des mots est inversé, mais la terminaison dit la fonction."},{"cle":{"type":"trous","trous":[["accusatif"],["nominatif"]]},"affichage":"accusatif · nominatif","explication":"« Le citoyen » est à l’**accusatif** (COD) et « la parole » au **nominatif** (sujet) : la phrase se traduit « la parole réjouit le citoyen »."},{"cle":{"type":"choix","ids":["a"]},"explication":"Au neutre, **nominatif et accusatif sont identiques** : la forme ne tranche pas, c’est le sens (un citoyen reçoit un don, pas l’inverse) qui le fait."}]$ex$::jsonb),
