  ('ac5c939a-baae-5da3-b2d1-8866a527c42a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Phidon, le rameur de Salamine, vote à l’Ecclésia","competence":"analyser-document","situation":"Phidon est un thète : trop pauvre pour s’acheter une armure, il rame sur un navire de guerre. Son histoire montre comment une victoire change le poids des plus pauvres dans la cité.","documents":[{"id":"phidon","type":"texte","genre":"recit","titre":"Le récit de Phidon","source":"Récit écrit pour l’exercice : le personnage est imaginé.","blocs":["Phidon est un thète : il ne possède pas assez de terre pour s’équiper en soldat. En 480 av. J.-C., il rame sur un navire de la flotte athénienne et participe à la victoire de Salamine.","Quelques années plus tard, il monte sur la Pnyx. On a désormais besoin de lui et des autres rameurs : il lève la main pour voter la guerre ou la paix."]},{"id":"batailles","type":"tableau","titre":"Les guerres médiques","source":"Dates tirées du cours.","colonnes":["Bataille","Date av. J.-C."],"lignes":[["Marathon",490],["Salamine",480],["Platées",479]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre ce que fait Phidon sur le navire.","aide":"C’est un verbe d’action : ce que font les rameurs.","type":"zone","document":"phidon","multiple":false},{"enonce":"Combien d’années séparent Marathon de Platées ?","aide":"Retranche 479 à 490 : les années avant J.-C. se comptent à rebours.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi la victoire de Salamine renforce-t-elle le poids des thètes ?","aide":"Qui fait avancer une flotte de guerre ?","type":"choix","options":[{"id":"a","texte":"Parce que les thètes ont payé les navires de leur argent"},{"id":"b","texte":"Parce que les rameurs de la flotte sont des citoyens pauvres"},{"id":"c","texte":"Parce que les thètes sont les chefs de l’armée de terre"},{"id":"d","texte":"Parce que les thètes sont élus stratèges après la victoire"}],"multiple":false},{"enonce":"Associe chaque bataille à ce qu’elle décide.","aide":"Salamine est une bataille de mer ; Platées clôt la série en 479.","type":"association","gauche":[{"id":"g0","texte":"Marathon"},{"id":"g1","texte":"Salamine"},{"id":"g2","texte":"Platées"}],"droite":[{"id":"d0","texte":"Victoire navale décisive"},{"id":"d1","texte":"Fin de l’invasion"},{"id":"d2","texte":"Première victoire terrestre sur les Perses"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22"]},"explication":"Phidon **rame** : c’est ce travail qui rend les thètes indispensables à la flotte."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11 ans","explication":"490 − 479 = **11 ans** : les guerres médiques s’étalent sur plus de dix ans."},{"cle":{"type":"choix","ids":["b"]},"explication":"Salamine est une bataille **navale** : les rameurs, citoyens pauvres, sont indispensables, donc écoutés à l’assemblée."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Marathon** est la première victoire sur terre, **Salamine** la victoire navale décisive, **Platées** met fin à l’invasion."}]$ex$::jsonb),
  ('ac5c939a-baae-5da3-b2d1-8866a527c42a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Lettre d’une cité alliée : démocratie chez soi, empire ailleurs","competence":"analyser-document","situation":"Un magistrat d’une petite cité de la ligue de Délos écrit à un ami. Sa lettre, mise en regard d’une frise, permet de comprendre comment Athènes, démocratie à l’intérieur, domine ses alliés.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un magistrat allié","source":"Lettre écrite pour l’exercice : la cité et le magistrat sont imaginés.","blocs":["Nous avons juré de défendre les Grecs contre les Perses. Mais le trésor n’est plus à Délos : il est à Athènes. Chaque année, nous versons le phoros, et nous voyons qu’on bâtit le Parthénon avec notre argent. Les cités qui se sont révoltées ont été écrasées."]},{"id":"frise","type":"frise","titre":"La ligue de Délos, Ve siècle av. J.-C.","source":"Frise établie d’après le cours.","debut":-480,"fin":-400,"pas":10,"evenements":[{"id":"z1","date":-478,"nom":"Ligue de Délos"},{"id":"z2","date":-454,"nom":"Trésor à Athènes"},{"id":"z3","date":-431,"nom":"Péloponnèse"}]}],"questions":[{"enonce":"Touche le mot qui désigne le tribut versé par les alliés.","aide":"Le mot est grec, il apparaît après « nous versons le ».","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche l’événement après lequel la ligue devient un instrument de domination.","aide":"Le magistrat dit que le trésor « n’est plus à Délos ».","type":"zone","document":"frise","multiple":false},{"enonce":"La lettre est écrite en 440 av. J.-C. Entre quels événements de la frise se place-t-elle ?","aide":"Compare 440 aux dates 454 et 431 de la frise.","type":"choix","options":[{"id":"a","texte":"Après le début de la guerre du Péloponnèse"},{"id":"b","texte":"Avant la fondation de la ligue de Délos"},{"id":"c","texte":"Entre la fondation de la ligue et le transfert"},{"id":"d","texte":"Entre le transfert du trésor et la guerre"}],"multiple":false},{"enonce":"Combien d’années séparent la fondation de la ligue de Délos (478) du début de la guerre du Péloponnèse (431) ?","aide":"Soustrais 431 à 478.","type":"nombre","unite":"ans"},{"enonce":"Complète la formule qui résume Athènes au Ve siècle.","aide":"Pense à ce que décident les citoyens, puis à ce que subissent les alliés.","type":"trous","segments":["Athènes est une ",0," à l’intérieur et un ",1," à l’extérieur."],"banque":["tyrannie","oligarchie","empire","démocratie"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"Le tribut s’appelle le **phoros** : il finance en partie le Parthénon."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le transfert du **trésor à Athènes** en 454 av. J.-C. fait de la ligue un instrument de domination."},{"cle":{"type":"choix","ids":["d"]},"explication":"454 est avant 440, et 431 est après : la lettre se place **entre le transfert du trésor et la guerre du Péloponnèse**."},{"cle":{"type":"nombre","valeur":47,"tolerance":0},"affichage":"47 ans","explication":"478 − 431 = **47 ans** : la ligue défensive est devenue en moins d’un demi-siècle un empire."},{"cle":{"type":"trous","trous":[["democratie"],["empire"]]},"affichage":"démocratie · empire","explication":"Athènes est une **démocratie** pour ses citoyens et un **empire** pour ses alliés, qui paient le phoros et ne peuvent pas quitter la ligue."}]$ex$::jsonb),
  ('5bd4b4bd-27c8-5212-a4bc-8026b11f95d1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Mare Nostrum : trois villes de l’Empire romain","competence":"lire-carte","situation":"Dans son cahier, Nora dessine la Méditerranée du temps des Romains et y place trois grandes villes de l’Empire. Elle doit retrouver chacune d’elles sur la carte.","documents":[{"id":"carte","type":"carte","titre":"Trois villes de l’Empire romain","source":"Carte d’après le cours.","fond":"mediterranee","lieux":[{"id":"z1","lieu":"rome","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"carthage","symbole":"lettre","lettre":"B"},{"id":"z3","lieu":"lugdunum","symbole":"lettre","lettre":"C"}]}],"questions":[{"enonce":"Rome mène trois guerres contre cette cité d’Afrique du Nord : Carthage. Touche-la.","aide":"Carthage se trouve près de l’actuelle Tunis, sur la côte sud de la Méditerranée.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les deux villes situées dans l’Europe d’aujourd’hui : Rome et Lugdunum, l’actuelle Lyon.","aide":"Elles sont au nord de la Méditerranée, l’une en Italie, l’autre en Gaule.","type":"zone","document":"carte","multiple":true},{"enonce":"La République romaine commence en 509 av. J.-C. et s’achève en 27 av. J.-C. Combien d’années dure-t-elle ?","aide":"Pour les dates avant J.-C., retranche la plus proche de J.-C. à la plus lointaine.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**B** est Carthage, sur la côte d’Afrique du Nord : c’est la grande rivale de Rome pendant les guerres puniques."},{"cle":{"type":"zone","ids":["z1","z3"]},"explication":"**A** est Rome, au centre de l’Italie, et **C** est Lugdunum, capitale des Gaules sur le Rhône : Carthage, au sud, est en Afrique."},{"cle":{"type":"nombre","valeur":482,"tolerance":0},"affichage":"482 ans","explication":"509 − 27 = **482 ans**. En 27 av. J.-C., Octave reçoit le nom d’Auguste et le Principat commence."}]$ex$::jsonb),
  ('5bd4b4bd-27c8-5212-a4bc-8026b11f95d1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Lucius découvre sa ville romaine","competence":"se-reperer-temps","situation":"Lucius, jeune Gaulois de Lugdunum, raconte en 150 comment sa ville est devenue romaine. Sa lettre et une frise permettent de comprendre ce que Rome change et quand.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Lucius, en l’an 150","source":"Lettre écrite pour l’exercice : le personnage est imaginé.","blocs":["Dans ma ville, rien ne ressemble à ce que racontait mon grand-père. Au centre, il y a un forum ; plus loin, des thermes et un amphithéâtre. Tout le monde parle latin et les routes empierrées nous relient au reste de l’Empire. Mon père, notable de la ville, siège au conseil."]},{"id":"frise","type":"frise","titre":"Rome, de la République à l’Empire","source":"Frise établie d’après le cours.","debut":-550,"fin":250,"pas":50,"periodes":[{"id":"z1","debut":-509,"fin":-27,"nom":"République","teinte":"ambre"}],"evenements":[{"id":"z2","date":-27,"nom":"Auguste"},{"id":"z3","date":117,"nom":"Trajan"},{"id":"z4","date":212,"nom":"Caracalla"}]}],"questions":[{"enonce":"Touche les trois éléments de la ville romaine que cite Lucius.","aide":"Cherche trois bâtiments : la place publique, les bains et le lieu des spectacles.","type":"zone","document":"lettre","multiple":true},{"enonce":"Touche l’événement qui accorde la citoyenneté romaine à presque tous les hommes libres de l’Empire.","aide":"C’est l’événement le plus récent de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’extension maximale de l’Empire sous Trajan (117) de l’édit de Caracalla (212) ?","aide":"Les deux dates sont après J.-C. : soustrais la plus petite à la plus grande.","type":"nombre","unite":"ans"},{"enonce":"Lucius vit en 150. Comment peut-il devenir citoyen romain à cette date ?","aide":"Regarde où se place 150 sur la frise par rapport à l’édit de Caracalla.","type":"choix","options":[{"id":"a","texte":"En payant chaque année un tribut au gouverneur romain"},{"id":"b","texte":"Automatiquement, parce qu’il est né à l’intérieur de l’Empire"},{"id":"c","texte":"En acceptant de quitter sa ville pour s’installer à Rome"},{"id":"d","texte":"Par une extension progressive, souvent accordée aux élites locales"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m22","m25"]},"explication":"Lucius cite le **forum**, les **thermes** et l’**amphithéâtre** : ces monuments font d’une ville gauloise une ville romaine."},{"cle":{"type":"zone","ids":["z4"]},"explication":"L’édit de **Caracalla**, en 212, accorde la citoyenneté à presque tous les hommes libres de l’Empire."},{"cle":{"type":"nombre","valeur":95,"tolerance":0},"affichage":"95 ans","explication":"212 − 117 = **95 ans**."},{"cle":{"type":"choix","ids":["d"]},"explication":"En 150, l’édit de 212 n’existe pas encore : la citoyenneté s’étend **progressivement aux provinciaux**, d’abord aux notables, qui diffusent ensuite le modèle romain."}]$ex$::jsonb),
  ('5bd4b4bd-27c8-5212-a4bc-8026b11f95d1'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quatre hommes en 212 : qui devient citoyen ?","competence":"analyser-document","situation":"En 212, l’empereur Caracalla accorde la citoyenneté à presque tous les hommes libres de l’Empire. Un fonctionnaire romain, quelques années plus tard, décrit les fragilités de cet empire.","documents":[{"id":"hommes","type":"tableau","titre":"Quatre hommes en 211","source":"Personnages imaginés pour l’exercice.","colonnes":["Prénom","Statut","Où vit-il ?"],"lignes":[["Marcus","Homme libre, non citoyen","Londinium, en Bretagne romaine"],["Quintus","Homme libre, non citoyen","Carthage, en Afrique"],["Zoticos","Esclave","Antioche, en Syrie"],["Bodo","Homme libre, hors de l’Empire","Au-delà du limes, en Germanie"]],"enteteLignes":true},{"id":"note","type":"texte","genre":"lettre","titre":"Note d’un fonctionnaire, vers 235","source":"Texte écrit pour l’exercice : le fonctionnaire est imaginé.","blocs":["Notre empire repose sur l’esclavage, sur l’armée qui garde le limes et sur des impôts lourds. Mais les invasions, les usurpations et la monnaie qui perd sa valeur ébranlent aujourd’hui tout l’édifice."]}],"questions":[{"enonce":"Après l’édit de Caracalla (212), qui devient citoyen romain ?","aide":"L’édit vise les hommes libres qui vivent dans l’Empire.","type":"categories","categories":[{"id":"c0","texte":"Devient citoyen"},{"id":"c1","texte":"Reste non citoyen"}],"items":[{"id":"i0","texte":"Bodo"},{"id":"i1","texte":"Marcus"},{"id":"i2","texte":"Zoticos"},{"id":"i3","texte":"Quintus"}]},{"enonce":"Touche les trois piliers sur lesquels, selon le fonctionnaire, repose l’Empire.","aide":"Cherche une institution sociale, une frontière et une charge financière.","type":"zone","document":"note","multiple":true},{"enonce":"Range ces événements du plus ancien au plus récent.","aide":"Les guerres puniques précèdent la dictature de César.","type":"ordre","items":[{"id":"a","texte":"Assassinat de Jules César (44 av. J.-C.)"},{"id":"b","texte":"Édit de Caracalla (212)"},{"id":"c","texte":"Guerres puniques contre Carthage"},{"id":"d","texte":"Extension maximale sous Trajan"},{"id":"e","texte":"Octave devient Auguste (27 av. J.-C.)"}]},{"enonce":"Que montre l’édit de 212 sur la manière dont Rome traite les peuples conquis ?","aide":"Pense à la phrase du cours sur les peuples conquis : Rome en fait des Romains.","type":"choix","options":[{"id":"a","texte":"Rome intègre les vaincus au lieu de les détruire"},{"id":"b","texte":"Rome supprime toutes les différences de condition"},{"id":"c","texte":"Rome réserve la citoyenneté aux soldats de l’armée"},{"id":"d","texte":"Rome renvoie les vaincus dans leurs terres d’origine"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**Marcus** et **Quintus** sont libres et vivent dans l’Empire : ils deviennent citoyens. **Zoticos** est esclave et **Bodo** vit hors de l’Empire : ils restent non citoyens."},{"cle":{"type":"zone","ids":["m5","m12","m16"]},"explication":"L’Empire repose sur l’**esclavage**, sur l’armée du **limes** et sur des **impôts** lourds."},{"cle":{"type":"ordre","ids":["c","a","e","d","b"]},"explication":"Guerres puniques, puis **César** (44 av. J.-C.), **Auguste** (27 av. J.-C.), **Trajan** (98-117), enfin **Caracalla** (212)."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’édit prolonge la politique romaine : les vaincus deviennent peu à peu des **Romains**, à leur rythme et selon les conditions de Rome. Les esclaves restent pourtant exclus."}]$ex$::jsonb),
  ('5ed749ae-702f-5f8a-9c53-08b3913d13d6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un siècle pour refonder l’Empire","competence":"se-reperer-temps","situation":"Samia résume sur une frise comment l’Empire romain se reconstruit au IVe siècle, après la crise du siècle précédent.","documents":[{"id":"frise","type":"frise","titre":"L’Empire romain au IVe siècle","source":"Frise établie d’après le cours.","debut":280,"fin":400,"pas":20,"evenements":[{"id":"z1","date":284,"nom":"Dioclétien"},{"id":"z2","date":312,"nom":"Pont Milvius"},{"id":"z3","date":330,"nom":"Constantinople"},{"id":"z4","date":395,"nom":"Partage"}]}],"questions":[{"enonce":"Touche l’événement qui voit naître une nouvelle capitale à l’Est.","aide":"Constantinople est fondée sur le site de Byzance.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la bataille du pont Milvius (312) de la fondation de Constantinople (330) ?","aide":"Soustrais la plus petite date à la plus grande.","type":"nombre","unite":"ans"},{"enonce":"Que met en place Dioclétien à partir de 284 ?","aide":"Le mot grec commence par « tétra » : quatre.","type":"choix","options":[{"id":"a","texte":"La religion chrétienne officielle de l’Empire"},{"id":"b","texte":"La tétrarchie, le gouvernement par quatre empereurs"},{"id":"c","texte":"Le Principat, le pouvoir d’un empereur unique"},{"id":"d","texte":"La République, le gouvernement par le Sénat"}],"multiple":false}]}$ex$::jsonb,
