  ('5ed749ae-702f-5f8a-9c53-08b3913d13d6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’édit de Milan : une liberté, pas une religion d’État","competence":"analyser-texte","situation":"Hugo lit un texte adapté de l’édit de Milan, puis le replace dans un tableau de dates. Il veut comprendre ce que l’édit accorde réellement aux chrétiens.","documents":[{"id":"edit","type":"texte","genre":"source","titre":"L’édit de Milan, 313","source":"D’après l’édit de Milan (313), texte adapté et raccourci.","blocs":["Nous avons décidé d’accorder aux chrétiens, comme à tous les autres, la liberté de suivre la religion qu’ils choisissent, afin que la divinité soit favorable à nous et à tous nos sujets."]},{"id":"dates","type":"tableau","titre":"Les étapes du christianisme dans l’Empire","source":"Dates tirées du cours.","colonnes":["Date","Événement"],"lignes":[["313","Édit de Milan"],["325","Concile de Nicée"],["330","Fondation de Constantinople"],["vers 380-392","Règne de Théodose"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce que l’édit accorde aux chrétiens et aux autres.","aide":"Le mot s’oppose à la persécution.","type":"zone","document":"edit","multiple":false},{"enonce":"Ce texte fait-il du christianisme la religion officielle de l’Empire ?","aide":"Relis : l’édit parle aux chrétiens « comme à tous les autres ».","type":"choix","options":[{"id":"a","texte":"Non, il accorde la liberté de culte à tous"},{"id":"b","texte":"Oui, il crée une Église placée sous l’empereur"},{"id":"c","texte":"Non, il continue à poursuivre les chrétiens"},{"id":"d","texte":"Oui, il interdit désormais tous les autres cultes"}],"multiple":false},{"enonce":"Touche l’empereur qui fait du christianisme la religion officielle de l’Empire.","aide":"C’est le règne le plus tardif du tableau.","type":"zone","document":"dates","multiple":false},{"enonce":"Associe chaque date à ce qu’elle apporte.","aide":"Nicée est un concile : une assemblée d’évêques.","type":"association","gauche":[{"id":"g0","texte":"313"},{"id":"g1","texte":"325"},{"id":"g2","texte":"330"},{"id":"g3","texte":"vers 380-392"}],"droite":[{"id":"d0","texte":"Une nouvelle capitale à l’Est"},{"id":"d1","texte":"La liberté de culte pour tous"},{"id":"d2","texte":"La querelle arienne est tranchée"},{"id":"d3","texte":"Une religion officielle"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"L’édit accorde la **liberté** de suivre sa religion, aux chrétiens comme aux autres."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’édit de Milan donne la **liberté de culte à tous**, chrétiens compris. Il ne fait pas du christianisme la religion officielle."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"C’est **Théodose**, vers 380-392 : le christianisme passe de religion protégée à religion officielle."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"313 : **liberté de culte** ; 325 : le concile de Nicée tranche la querelle sur la nature du Christ ; 330 : **Constantinople** ; 380-392 : le christianisme devient **religion officielle**."}]$ex$::jsonb),
  ('5ed749ae-702f-5f8a-9c53-08b3913d13d6'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Pourquoi Constantin choisit-il Byzance ?","competence":"analyser-document","situation":"Vers 324, un conseiller de l’empereur explique pourquoi la nouvelle capitale ne doit pas être Rome. La carte et son texte permettent de comprendre un choix stratégique.","documents":[{"id":"carte","type":"carte","titre":"L’Empire romain et ses frontières au IVe siècle","source":"Carte d’après le cours.","fond":"mediterranee","fleuves":["danube","euphrate"],"lieux":[{"id":"z1","lieu":"rome","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"byzance","symbole":"lettre","lettre":"B"},{"id":"z3","lieu":"antioche","symbole":"lettre","lettre":"C"},{"id":"z4","lieu":"alexandrie","symbole":"lettre","lettre":"D"}]},{"id":"conseil","type":"texte","genre":"lettre","titre":"Le conseil d’un proche de l’empereur","source":"Texte écrit pour l’exercice : le conseiller est imaginé.","blocs":["Rome est loin du Danube et de l’Euphrate, là où les ennemis menacent. Byzance, elle, est placée entre l’Europe et l’Asie : elle tient les détroits, elle est proche des frontières et des riches provinces d’Orient."]}],"questions":[{"enonce":"Constantin fonde en 330 une capitale sur le site de Byzance. Touche-la.","aide":"Cherche la ville entre l’Europe et l’Asie, sur les détroits qui mènent à la mer Noire.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le mot qui explique l’avantage commercial et militaire du site.","aide":"Le mot désigne des passages étroits entre deux mers.","type":"zone","document":"conseil","multiple":false},{"enonce":"Pourquoi Rome est-elle moins bien placée que Byzance pour gouverner l’Empire au IVe siècle ?","aide":"Regarde les deux fleuves sur la carte, puis la position de Rome.","type":"choix","options":[{"id":"a","texte":"Elle ne possède plus aucun bâtiment pour accueillir l’empereur"},{"id":"b","texte":"Elle est trop loin des frontières menacées et des provinces riches"},{"id":"c","texte":"Elle a été détruite par les troupes de Constantin en 312"},{"id":"d","texte":"Elle est trop proche du Danube et de ses invasions"}],"multiple":false},{"enonce":"Range ces étapes de la refondation de l’Empire de la plus ancienne à la plus récente.","aide":"Constantin règne seul avant de fonder sa capitale.","type":"ordre","items":[{"id":"a","texte":"Constantin l’emporte au pont Milvius (312)"},{"id":"b","texte":"Dioclétien instaure la tétrarchie (284)"},{"id":"c","texte":"Fondation de Constantinople (330)"},{"id":"d","texte":"Partage définitif de l’Empire (395)"},{"id":"e","texte":"Constantin règne seul (324)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**B** est Byzance, future Constantinople : elle domine les détroits entre Europe et Asie."},{"cle":{"type":"zone","ids":["m27"]},"explication":"Byzance **tient les détroits** : elle contrôle le passage entre la mer Noire et la Méditerranée."},{"cle":{"type":"choix","ids":["b"]},"explication":"Rome est **éloignée** du Danube et de l’Euphrate : réagir vite aux menaces est plus facile depuis Byzance, qui est aussi près des riches provinces d’Orient."},{"cle":{"type":"ordre","ids":["b","a","e","c","d"]},"explication":"**284**, **312**, **324**, **330**, puis **395** : en un siècle, l’Empire se refonde autour d’un pouvoir fort, d’une capitale à l’Est et d’une religion soutenue."}]$ex$::jsonb),
  ('e95ff08a-39a9-5560-951e-f5c0b7c79177'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois mondes autour de la Méditerranée","competence":"lire-carte","situation":"Au XIIe siècle, trois mondes se partagent la Méditerranée. Léa repère sur une carte leurs principales villes pour retrouver quel monde elles représentent.","documents":[{"id":"carte","type":"carte","titre":"Six villes de la Méditerranée médiévale","source":"Carte d’après le cours.","fond":"mediterranee","lieux":[{"id":"z1","lieu":"constantinople","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"rome","symbole":"lettre","lettre":"B"},{"id":"z3","lieu":"bagdad","symbole":"lettre","lettre":"C"},{"id":"z4","lieu":"le-caire","symbole":"lettre","lettre":"D"},{"id":"z5","lon":-4.78,"lat":37.89,"symbole":"lettre","lettre":"E"},{"id":"z6","lieu":"jerusalem","symbole":"lettre","lettre":"F"}]}],"questions":[{"enonce":"Touche la capitale de l’Empire byzantin, Constantinople.","aide":"Elle se trouve à l’entrée de la mer Noire, entre l’Europe et l’Asie.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les trois grands centres du monde musulman médiéval : Bagdad, Le Caire et Cordoue.","aide":"Bagdad est à l’est, Le Caire en Égypte, Cordoue au sud de l’Espagne.","type":"zone","document":"carte","multiple":true},{"enonce":"En 1099, la première croisade prend la ville marquée F. De quelle ville s’agit-il ?","aide":"L’appel de 1095 à Clermont demandait de la délivrer.","type":"choix","options":[{"id":"a","texte":"Le Caire"},{"id":"b","texte":"Bagdad"},{"id":"c","texte":"Jérusalem"},{"id":"d","texte":"Rome"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**A** est Constantinople, centre d’un empire chrétien d’Orient, héritier de Rome."},{"cle":{"type":"zone","ids":["z3","z4","z5"]},"explication":"**C** (Bagdad), **D** (Le Caire) et **E** (Cordoue) sont les grands centres d’un monde musulman riche, urbain et savant."},{"cle":{"type":"choix","ids":["c"]},"explication":"La ville F est **Jérusalem**, prise par les croisés en 1099, qui fondent les États latins d’Orient."}]$ex$::jsonb),
  ('e95ff08a-39a9-5560-951e-f5c0b7c79177'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un marchand génois suit les croisés","competence":"analyser-document","situation":"Un marchand génois fournit des navires aux croisés. Sa lettre et une frise montrent que les croisades ne sont pas qu’une guerre sainte.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un marchand génois","source":"Lettre écrite pour l’exercice : le marchand est imaginé.","blocs":["Je fournis des navires aux croisés qui partent pour la Terre sainte. En échange, notre ville m’a promis un comptoir dans les ports de Syrie : un quartier où nous pourrons commercer librement. Je ne vais pas à Jérusalem pour prier, mais pour que Gênes s’enrichisse."]},{"id":"frise","type":"frise","titre":"Les croisades, 1099-1291","source":"Frise établie d’après le cours.","debut":1080,"fin":1300,"pas":20,"evenements":[{"id":"z1","date":1099,"nom":"Jérusalem prise"},{"id":"z2","date":1187,"nom":"Saladin"},{"id":"z3","date":1204,"nom":"Constantinople"},{"id":"z4","date":1291,"nom":"Acre"}]}],"questions":[{"enonce":"Touche l’événement qui met fin à la présence latine en Orient.","aide":"C’est le dernier événement de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années les croisés ont-ils tenu Jérusalem, de leur prise de la ville (1099) à sa reprise par Saladin (1187) ?","aide":"Soustrais la date de la prise à celle de la reprise.","type":"nombre","unite":"ans"},{"enonce":"Touche le mot qui montre ce que le marchand espère obtenir en échange de son aide.","aide":"C’est un lieu de commerce, pas une terre ni un titre.","type":"zone","document":"lettre","multiple":false},{"enonce":"Lequel de ces événements oppose des chrétiens à d’autres chrétiens ?","aide":"Constantinople est la capitale de l’Empire byzantin chrétien.","type":"choix","options":[{"id":"a","texte":"La chute d’Acre (1291)"},{"id":"b","texte":"Le pillage de Constantinople (1204)"},{"id":"c","texte":"La prise de Jérusalem (1099)"},{"id":"d","texte":"La reprise par Saladin (1187)"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"La chute d’**Acre**, en 1291, met fin à la présence des Latins en Orient."},{"cle":{"type":"nombre","valeur":88,"tolerance":0},"affichage":"88 ans","explication":"1187 − 1099 = **88 ans**."},{"cle":{"type":"zone","ids":["m20"]},"explication":"Il espère un **comptoir** : les villes italiennes gagnent des quartiers marchands en Orient."},{"cle":{"type":"choix","ids":["b"]},"explication":"En **1204**, la quatrième croisade pille Constantinople, cité chrétienne : la croisade n’est pas toujours dirigée contre l’Islam."}]$ex$::jsonb),
  ('e95ff08a-39a9-5560-951e-f5c0b7c79177'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Reconquista et Sicile : conflits et cohabitations","competence":"analyser-document","situation":"En Espagne et en Sicile, les trois mondes se combattent mais vivent aussi côte à côte. Une carte et le récit d’un voyageur permettent de le comprendre.","documents":[{"id":"carte","type":"carte","titre":"Deux lieux de la Méditerranée médiévale","source":"Carte d’après le cours.","fond":"mediterranee","cadrage":[-12,28,40,48],"lieux":[{"id":"z1","lon":-4.02,"lat":39.86,"symbole":"lettre","lettre":"A"},{"id":"z2","lon":13.36,"lat":38.12,"symbole":"lettre","lettre":"B"}]},{"id":"recit","type":"texte","genre":"recit","titre":"Un voyageur à Palerme","source":"Récit écrit pour l’exercice : le voyageur est imaginé.","blocs":["À Palerme, au XIIe siècle, un voyageur note : « Dans la même rue, il y a une église, une mosquée et une synagogue. Au marché, on parle grec, arabe et latin. » La Sicile est désormais gouvernée par les Normands, mais elle fut longtemps arabe."]}],"questions":[{"enonce":"Les chrétiens reprennent cette ville d’Espagne en 1085 : Tolède. Touche-la.","aide":"Tolède est située au centre de l’Espagne, loin des côtes.","type":"zone","document":"carte","multiple":false},{"enonce":"Le voyageur du récit est à Palerme, en Sicile. Touche cette ville.","aide":"La Sicile est la grande île au sud de l’Italie.","type":"zone","document":"carte","multiple":false},{"enonce":"Range ces étapes de la Reconquista de la plus ancienne à la plus récente.","aide":"La Reconquista s’achève avec la dernière ville musulmane d’Espagne.","type":"ordre","items":[{"id":"a","texte":"Prise de Grenade (1492)"},{"id":"b","texte":"Prise de Tolède (1085)"},{"id":"c","texte":"Victoire de Las Navas de Tolosa (1212)"}]},{"enonce":"Touche les trois langues parlées au marché de Palerme.","aide":"Elles correspondent aux chrétiens d’Orient, aux musulmans et aux chrétiens latins.","type":"zone","document":"recit","multiple":true},{"enonce":"En terre d’Islam, juifs et chrétiens relèvent de la dhimma. Que leur apporte ce statut ?","aide":"Le statut protège, mais pas gratuitement.","type":"choix","options":[{"id":"a","texte":"L’obligation de se convertir dans l’année"},{"id":"b","texte":"L’égalité totale de droits avec les musulmans"},{"id":"c","texte":"L’expulsion hors des villes musulmanes"},{"id":"d","texte":"La protection, contre un impôt et un statut inférieur"}],"multiple":false}]}$ex$::jsonb,
