  ('044ba34c-8578-540a-9297-c74e8013df33'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dans la cale d’un navire génois, à Alexandrie","competence":"lire-tableau","situation":"Un navire de Gênes vient d’accoster à Alexandrie. Son registre de cargaison indique ce qu’il a chargé à l’aller et ce qu’il rapportera : il permet de comprendre ce que les marchands italiens vendent et achètent en Orient.","documents":[{"id":"registre","type":"fiche","modele":"ticket","entete":"Registre du navire génois","sousTitre":"Alexandrie, XIIIe siècle","emoji":"⚓","source":"Registre imaginé pour l’exercice.","lignes":[{"texte":"Draps de laine","valeur":"50 balles","id":"z1"},{"texte":"Épices","valeur":"30 sacs","id":"z2"},{"texte":"Barres de fer et d’étain","valeur":"20 barres","id":"z3"},{"texte":"Soie","valeur":"12 balles","id":"z4"},{"texte":"Poutres de bois","valeur":"40 poutres","id":"z5"},{"texte":"Sucre","valeur":"25 caisses","id":"z6"}],"pied":"Écrit pour l’exercice","teinte":"bleu"}],"questions":[{"enonce":"Touche les trois marchandises que les marchands italiens vendent en Orient : draps, métaux et bois.","aide":"Ce sont des produits de l’Occident ; les épices, la soie et le sucre viennent d’Orient.","type":"zone","document":"registre","multiple":true},{"enonce":"Combien de sacs, de balles et de caisses de marchandises achetées en Orient (épices, soie et sucre) le navire rapportera-t-il au total ?","aide":"Additionne les trois quantités, sans tenir compte de l’unité.","type":"nombre","unite":"colis"},{"enonce":"À quoi servent les fondouks que Gênes, Venise et Pise installent dans les ports d’Orient ?","aide":"Le fondouk est un comptoir marchand.","type":"choix","options":[{"id":"a","texte":"À fortifier le port contre les attaques des pirates"},{"id":"b","texte":"À frapper la monnaie utilisée par les marchands"},{"id":"c","texte":"À former les marins aux techniques de navigation"},{"id":"d","texte":"À stocker les marchandises et à loger les marchands"}],"multiple":false}]}$ex$::jsonb,
