   $ex${"titre":"Un « bien meuble » : lire le Code noir","competence":"analyser-texte","situation":"Samuel lit un résumé d’un article du Code noir de 1685, puis place dans un tableau les grandes dates de l’esclavage dans les colonies françaises. Il doit comprendre ce que dit le texte et le situer.","documents":[{"id":"code","type":"texte","genre":"source","titre":"Le Code noir, 1685","source":"D’après le Code noir (1685), article 44, texte adapté et résumé.","blocs":["Les esclaves sont déclarés meubles : ils entrent dans les biens de leur maître, comme n’importe quel objet que l’on possède."]},{"id":"dates","type":"tableau","titre":"L’esclavage dans les colonies françaises","source":"Dates tirées du cours.","colonnes":["Événement","Date"],"lignes":[["Code noir",1685],["Première abolition française",1794],["Rétablissement de l’esclavage par Bonaparte","?"],["Abolition définitive",1848]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit quel statut le texte donne aux esclaves.","aide":"Le mot désigne les biens que l’on peut déplacer, comme des objets.","type":"zone","document":"code","multiple":false},{"enonce":"Que révèle ce statut de « bien meuble » ?","aide":"Un meuble s’achète, se vend et se transmet.","type":"choix","options":[{"id":"a","texte":"L’esclave est traité comme un bien, non comme une personne"},{"id":"b","texte":"L’esclave est protégé comme un citoyen par la loi"},{"id":"c","texte":"L’esclave est payé pour son travail comme un salarié"},{"id":"d","texte":"L’esclave est libre de quitter la plantation à son gré"}],"multiple":false},{"enonce":"Combien d’années séparent le Code noir (1685) de la première abolition française (1794) ?","aide":"Soustrais 1685 à 1794.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque forme de résistance à ce qu’elle désigne.","aide":"Le marronnage est la fuite hors de la plantation.","type":"association","gauche":[{"id":"g0","texte":"Le marronnage"},{"id":"g1","texte":"Les révoltes"},{"id":"g2","texte":"Le sabotage"}],"droite":[{"id":"d0","texte":"Des soulèvements armés, réprimés"},{"id":"d1","texte":"Un refus quotidien et discret"},{"id":"d2","texte":"La fuite et les communautés d’évadés"}]},{"enonce":"Complète le tableau : en quelle année Bonaparte rétablit-il l’esclavage dans les colonies françaises ?","aide":"C’est après la première abolition (1794) et avant l’abolition définitive (1848).","type":"nombre"}]}$ex$::jsonb,
